/// <summary>
/// SalesInvoiceHeaderV4Entity COC class
/// </summary>
[ExtensionOf(tableStr(SalesInvoiceHeaderV4Entity))]
final class METSalesInvoiceHeaderV4Entity_Extension
{
}

Method.Source:
/// <summary>
/// Map data fields to virtual fields
/// </summary>
public void postLoad()
{
    next postLoad();

    changecompany(this.DataAreaId)
    {
        SysDocuBrandDetails sysDocuBrandDetails;

        select firstonly METTaxRegNumber from sysDocuBrandDetails
            where sysDocuBrandDetails.ReportName == METConstants::METSalesInvoice
            && sysDocuBrandDetails.METIndustryKey == this.METIndustryKey;

        this.METStoreId = this.getMETCustomerAttribute(this.InvoiceCustomerAccountNumber, METConstants::StoreId);
        this.METTaxRegNumber = sysDocuBrandDetails.METTaxRegNumber;
        this.METInvoiceTotalGST = this.getMETGSTAmount();
        this.METInvoiceTotalWET = this.getMETWETAmount();
        this.METInvoiceTotalWEG = this.getMETWEGAmount();
        this.METTotalNetWeight = this.getMETNetWeight();
    }
}

/// <summary>
/// Method to return tax amount
/// </summary>
/// <param name = "_taxCode">Tax code (GST, WET, WEG)</param>
/// <returns>Tax amount</returns>
public TaxAmountCur calculateTaxAmount(TaxCode  _taxCode = '')
{
    TaxAmountCur    taxAmount;

    TaxTrans taxTrans;

    if (_taxCode == METConstants::taxGroupGST)
    {
        select sum(SourceRegulateAmountCur) from taxTrans
                where taxTrans.TransDate == this.InvoiceDate
                    && taxTrans.Voucher == this.LedgerVoucher
                    && (taxTrans.TaxCode == _taxCode || taxTrans.TaxCode == METConstants::WEG);
    }
    else
    {
        select sum(SourceRegulateAmountCur) from taxTrans
                where taxTrans.TransDate == this.InvoiceDate
                    && taxTrans.Voucher == this.LedgerVoucher
                    && taxTrans.TaxCode == _taxCode;
    }

    taxAmount = -1*taxTrans.SourceRegulateAmountCur;

    return taxAmount;
}

/// <summary>
/// Get GST amount
/// </summary>
/// <returns>GST amount</returns>
public TaxRegulationAmountCur getMETGSTAmount()
{
    return this.calculateTaxAmount(METConstants::taxGroupGST);
}

/// <summary>
/// Get WET amount
/// </summary>
/// <returns>WET amount</returns>
public TaxRegulationAmountCur getMETWETAmount()
{
    return this.calculateTaxAmount(METConstants::WET);
}

/// <summary>
/// Get WEG amount
/// </summary>
/// <returns>WEG amount</returns>
public TaxRegulationAmountCur getMETWEGAmount()
{
    return this.calculateTaxAmount(METConstants::WEG);
}

/// <summary>
/// Method to return net weight
/// </summary>
/// <returns>Net weight</returns>
public METNetWeight getMETNetWeight()
{
    SalesLine salesLine;
    InventDim inventDim;
    METNetWeight totalNetWeight;
    METWHSPhysDimUOMSite metWHSPhysDimUOMSite;

    select sum(NetWeight) from metWHSPhysDimUOMSite
        join salesLine
            where salesLine.ItemId == metWHSPhysDimUOMSite.ItemId
               && salesLine.SalesUnit == metWHSPhysDimUOMSite.UOM
               && salesLine.SalesId == this.SalesOrderNumber
        join inventDim
            where inventDim.InventDimId == salesLine.InventDimId
               && inventDim.InventSiteId == metWHSPhysDimUOMSite.SiteId;

    totalNetWeight = metWHSPhysDimUOMSite.NetWeight;

    return totalNetWeight;
}

/// <summary>
/// Bu348309 CB372 - V7 + V8 - E-invoice is not performant and requires design changes
/// Fetch the text valud of the customer attribute
/// </summary>
/// <param name = "_custId">_custId</param>
/// <param name = "_name">_name</param>
/// <returns>AttributeValueText</returns>
public AttributeValueText getMETCustomerAttribute(AccountNum _custId, Name _name)
{
    ecoResValue ecoResValue;
    ecoResAttributeValue ecoResAttributeValue;
    ecoResAttribute ecoResAttribute;
    ecoResAttributeType ecoResAttributeType;
    ecoResInstanceValue ecoResInstanceValue;
    CustomerInstanceValue customerInstanceValue;
    EcoResTextValue ecoResTextValue;

    select firstonly recId from ecoResAttributeValue
        join RecId from ecoResAttribute
            where ecoResAttributeValue.Attribute == ecoResAttribute.RecId
        join RecId from ecoResAttributeType
            where ecoResAttribute.AttributeType == ecoResAttributeType.RecId
        join ecoResInstanceValue
            where ecoResAttributeValue.InstanceValue == ecoResInstanceValue.RecId
        join AccountNum,recId from customerInstanceValue
            where customerInstanceValue.RecId == ecoResInstanceValue.RecId
        join RecId from ecoResValue
            where ecoResAttributeValue.Value == ecoResValue.RecId && customerInstanceValue.AccountNum == _custId
        join textvalue from ecoResTextValue
            where ecoResTextValue.RecId == ecoResValue.RecId
                && ecoResAttribute.Name == _name;

    return ecoResTextValue.textvalue;
}
